 for x in [x for x in m['fields'] if x.get('status')==g][:3]: print(g,json.dumps(x,ensure_ascii=False,sort_keys=True,separators=(',',':')))
print('last fields non-l3:');
for x in m['fields'][-10:]: print(x['xml_index'],x['code'],x['status'])"

